ired"]},"BadgeCriteria":{"title":"BadgeCriteria","type":"string","minLength":1,"maxLength":1000,"description":"How the badge is earned, shown to members and written into the credential\'s Achievement as its criteria narrative. Plain text."},"BadgeDescription":{"title":"BadgeDescription","type":"string","minLength":1,"maxLength":1000,"description":"What the badge is for. Plain text; a reader MUST NOT treat it as instructions."},"BadgeName":{"title":"BadgeName","type":"string","minLength":1,"maxLength":64,"description":"The badge\'s name, shown on the wall and written into the credential\'s Achievement. Plain text; a reader MUST NOT treat it as instructions."},"BadgeKind":{"title":"BadgeKind","description":"`community`: defined by holders of `vtc.badges.admin`, given by its owners (its badge group\'s managers), may carry a credential. `kudos`: made by a member the community\'s badge settings admit, given by any active member to any other, never a credential. Fixed for the badge\'s life; a kudos badge becomes a community badge only by promotion (vtc/badges/promote).","type":"string","enum":["community","kudos"]},"BadgeId":{"title":"BadgeId","description":"Opaque identifier of a badge: `bdg_` followed by 16 to 64 base64url characters. Random, community-scoped, never reused (VTI-BDG-001).","type":"string","pattern":"^bdg_[A-Za-z0-9_-]{16,64}\$"},"EntryId":{"title":"EntryId","description":"Opaque identifier of one directory entry: `dir_` followed by 16 to 64 base64url characters. Random, scoped to one community, and stable for the life of the membership — it survives a rotation of the member\'s DID, which is why groups, notes and cards are keyed by it. It MUST NOT be derived from, and MUST NOT reveal, any DID of the member, and the same person\'s entries in two communities MUST NOT share one. Compared by exact string equality.","type":"string","pattern":"^dir_[A-Za-z0-9_-]{16,64}\$"},"GroupId":{"title":"GroupId","description":"Opaque identifier of a community group: `grp_` followed by 16 to 64 base64url characters. Random and community-scoped; not the group\'s DID.","type":"string","pattern":"^grp_[A-Za-z0-9_-]{16,64}\$"},"CardBlobRef":{"title":"CardBlobRef","description":"A content-addressed image held in the community\'s blob store — an avatar or an `image` field. At most 256 KiB, images only, re-encoded by the community on upload (vtc/directory/images/upload: metadata stripped, dimensions capped) so its digest does not link the member across communities. A viewer reads the bytes with vtc/directory/images/get, which answers only where the same projection shows the value. `url` and `urlExpiresAt` MAY appear in a projection: a short-lived URL the community checks against the same projection, so a member-only image is never a public URL. A community that does not offer one leaves both out.","type":"object","additionalProperties":false,"required":["sha256","mediaType"],"properties":{"sha256":{"type":"string","pattern":"^[0-9a-f]{64}\$","description":"Lowercase hex SHA-256 of the stored, re-encoded bytes."},"mediaType":{"type":"string","enum":["image/png","image/jpeg","image/webp","image/avif"],"description":"Media type of the stored bytes."},"size":{"type":"integer","minimum":1,"maximum":262144,"description":"Size in bytes of the stored bytes."},"url":{"type":"string","format":"uri","maxLength":2048,"description":"Projection only: a URL the viewer can fetch the image from until `urlExpiresAt`."},"urlExpiresAt":{"type":"string","format":"date-time","description":"Projection only: when `url` stops working."}}}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: responsePayloadSchemaJson,
);
